import assert from 'node:assert/strict';
import {buildExplainability} from '../../../lib/credit-engine/explainability/engine.ts';
import {validateExplainabilityOutput} from '../../../lib/credit-engine/explainability/validation.ts';
import {EXPLAINABILITY_POLICY} from '../../../lib/credit-engine/explainability/policy.ts';
import {at,stable,rank,id} from '../../../lib/credit-engine/explainability/common.ts';
import {recommendationCopy} from '../../../lib/credit-engine/explainability/recommendations.ts';
import {reorder} from './builders.mjs';
export function checkExpectations(e,o){const x=e.input,ex=e.expectations,find=c=>o.claims.filter(v=>v.claimCode===c);if(ex.status)assert.equal(o.status,ex.status);checkStructuredExpectations(ex,o);for(const c of ex.required??[])assert.ok(find(c).length,'Missing '+c);for(const c of ex.forbidden??[])assert.equal(find(c).length,0,'Forbidden '+c);if(ex.text)assert.ok(find(ex.text[0]).some(c=>c.textRu.toLowerCase().includes(ex.text[1].toLowerCase())),'Missing text '+ex.text);for(const k of ['severity','confidence'])if(ex[k])assert.ok(find(ex[k][0]).every(c=>c[k]===ex[k][1])&&find(ex[k][0]).length,k+' '+ex[k]);if(ex.binding)assert.ok(o.valueBindings.some(b=>b.bindingCode===ex.binding[0]&&b.rawValue===ex.binding[1]),'Binding '+ex.binding);if(ex.components)assert.equal(o.claims.filter(c=>c.claimKind==='INDEX_COMPONENT').length,ex.components);
 if(ex.defect){const f=x.riskAssessment.findings.find(f=>f.code==='RISK-BKI-CURRENT-OVERDUE');assert.ok(f);assert.equal(f.severity,'MEDIUM');assert.equal(x.riskAssessment.evaluations.find(e=>e.ruleCode==='RISK-BKI-HISTORICAL-DELINQUENCY').status,'NOT_TRIGGERED');assert.equal(find('RISK-BKI-HISTORICAL-DELINQUENCY').length,0);assert.ok(find('RISK-BKI-CURRENT-OVERDUE').length);for(const code of ['DELINQUENCY_1_29','DELINQUENCY_30_59','DELINQUENCY_60_PLUS']){assert.ok(!f.reasonCodes.includes(code));assert.ok(!JSON.stringify(o).includes(code));}}
 if(ex.dataQuality)for(const c of o.claims.filter(c=>c.claimKind==='DATA_LIMITATION'&&c.riskFindingIds.length))assert.ok(c.textRu.includes('Ограничение относится к качеству или полноте данных.'));
 if(ex.noCreditRisk)assert.equal(x.riskAssessment.findings.filter(f=>f.scope==='CREDIT_RISK').length,0);if(ex.conservativeDecline)assert.ok(x.debtCapacity.operatingBasis.conservativeOperatingBasis.value<x.debtCapacity.operatingBasis.centralOperatingBasis.value);if(ex.noInventedFindings)assert.deepEqual(o.claims.filter(c=>['FINDING','DATA_LIMITATION'].includes(c.claimKind)&&c.claimCode.startsWith('RISK-')).map(c=>c.claimCode).sort(),x.riskAssessment.findings.map(f=>f.code).sort());
 if(ex.debtRouting){const cs=x.prescoreIndex.contributions.filter(c=>c.riskCode==='RISK-CF-DEBT-SERVICE-BURDEN');assert.ok(cs.length);for(const c of cs){assert.equal(c.component,'DEBT_CREDIT');assert.ok(o.claims.some(v=>v.indexContributionIds.includes(c.contributionId)&&v.valueBindings.some(b=>b.bindingCode==='component'&&b.rawValue==='DEBT_CREDIT')));}}
 if(ex.driverCopy)for(const d of o.driverExplanations){const src=x.creditAssessment.drivers.find(v=>v.driverId===d.driverId);for(const k of ['basePenaltyPoints','contextModifierPercent','finalPenaltyPoints','dimension'])assert.equal(d[k],src[k]);}
 if(ex.readinessCopy)for(const k of ['level','baseLevel','uncertaintyCapApplied'])assert.equal(find('READINESS')[0].valueBindings.find(b=>b.bindingCode===k).rawValue,x.financingReadiness[k]);
 if(ex.capacityCopy)for(const b of o.claims.filter(c=>c.claimKind==='CAPACITY').flatMap(c=>c.valueBindings))assert.equal(b.rawValue,at(x,b.canonicalPath));
 if(ex.productCopy)for(const c of x.productSelection.candidates){const claim=find('PRODUCT:'+c.productFamily)[0];assert.equal(claim.status,c.fitLevel);assert.deepEqual(claim.portfolioObligationIds,c.portfolioObligationIds);}
 if(ex.contextCopy)for(const r of x.contextAssessment.relations)assert.ok(o.claims.some(c=>c.contextRelationIds.includes(r.relationId)&&c.status===r.effect));
 if(ex.recommendationCopy)checkCopy(x,o);
 if(ex.portfolioSeparation){assert.equal(x.creditPortfolio.summary.fundedDebt.knownAmount,0);assert.ok(!JSON.stringify(o).includes('fake total debt'));}
 if(ex.noForcedRerun){assert.equal(x.actionPlan.day7.rerunRecommended,false);assert.ok(!o.claims.some(c=>c.textRu.includes('Вернитесь через')));}
 if(ex.clientDeclared){assert.ok(o.sourceReferences.some(s=>s.sourceKind==='CLIENT_DECLARATION'));assert.ok(o.claims.some(c=>c.textRu.includes('заявленным клиентом')));}
 if(ex.noPromises)assert.ok(!/банк отказал|банк одобрит|гарантированно|Index вырастет/i.test(o.claims.map(c=>c.textRu).join(' ')));
 if(ex.deterministicReorder)assert.equal(JSON.stringify(o),JSON.stringify(buildExplainability(reorder(x))));
}
export function checkBindings(x,o){for(const b of o.valueBindings)assert.equal(b.rawValue,at(x,b.canonicalPath));validateExplainabilityOutput(x,o,EXPLAINABILITY_POLICY);}
export function checkSources(x,o){const ids=new Set(o.sourceReferences.map(s=>s.sourceReferenceId));for(const c of o.claims){assert.ok(c.sourceReferenceIds.length);for(const id of c.sourceReferenceIds)assert.ok(ids.has(id));}for(const s of o.sourceReferences)assert.ok(at(x,s.canonicalPath));assert.equal(ids.size,o.sourceReferences.length);}
export function checkLineage(x,o){const sets={riskFindingIds:x.riskAssessment.findings.map(f=>f.findingId),riskFactIds:x.riskAssessment.facts.map(f=>f.factId),contextFactIds:x.contextAssessment.facts.map(f=>f.factId),contextRelationIds:x.contextAssessment.relations.map(f=>f.relationId),indexContributionIds:x.prescoreIndex.contributions.map(f=>f.contributionId),assessmentDriverIds:x.creditAssessment.drivers.map(f=>f.driverId),assessmentLimitationIds:x.creditAssessment.limitations.map(f=>f.limitationId),readinessConstraintIds:x.financingReadiness.constraints.map(f=>f.constraintId),recommendationIds:x.recommendationSet.recommendations.map(f=>f.recommendationId),planItemIds:x.actionPlan.items.map(f=>f.planItemId)};for(const c of o.claims)for(const [k,ids]of Object.entries(sets))for(const id of c[k])assert.ok(ids.includes(id),k+':'+id);for(const s of o.sections)for(const id of s.claimIds)assert.ok(o.claims.some(c=>c.claimId===id));}
export function checkCopy(x,o){for(const c of o.claims.filter(c=>c.sourceCopy)){const src=c.claimKind==='RECOMMENDATION'?x.recommendationSet.recommendations.find(r=>r.recommendationId===c.recommendationIds[0]):x.actionPlan.items.find(i=>i.planItemId===c.planItemIds[0]);assert.deepEqual(c.sourceCopy,recommendationCopy(src));assert.equal(c.titleRu,src.titleRu);assert.equal(c.textRu,src.actionSummaryRu);}for(const h of [x.actionPlan.day7,x.actionPlan.day30,x.actionPlan.day60])assert.deepEqual(o.claims.find(c=>c.claimCode==='HORIZON:'+h.horizon).planItemIds,h.focusItems.map(i=>i.planItemId));}
export function checkConfidence(x,o){for(const c of o.claims){assert.equal(c.confidence,c.evidenceStrength);for(const id of c.sourceReferenceIds)assert.ok(rank(c.confidence)<=rank(o.sourceReferences.find(s=>s.sourceReferenceId===id).confidence));}for(const v of [x.creditAssessment,x.actionPlan,x.recommendationSet])assert.ok(rank(o.confidence)<=rank(v.confidence));if(o.comparable)assert.ok(o.status==='GENERATED'&&x.creditAssessment.comparable&&x.actionPlan.comparable);const e=o.executiveSummary;assert.ok(e.keyFactorClaimIds.length<=5&&e.productClaimIds.length<=3&&e.currentFocusClaimIds.length<=5&&e.dataLimitationClaimIds.length<=3);}
export function runExplainabilityPack(entries){return {total:entries.length,results:entries.map(e=>{try{const before=stable(e.input),o=buildExplainability(e.input);checkExpectations(e,o);checkBindings(e.input,o);checkSources(e.input,o);checkLineage(e.input,o);checkCopy(e.input,o);checkConfidence(e.input,o);assert.equal(stable(e.input),before);return {caseId:e.caseId,result:'PASS',claimCount:o.claims.length,fingerprint:id('explanation-golden',stable(o))};}catch(error){return {caseId:e.caseId,result:'FAIL',error:error.message};}})};}

export function checkStructuredExpectations(ex,o){
 if(ex.overallConfidence)assert.equal(o.confidence,ex.overallConfidence);if(ex.comparable!==undefined)assert.equal(o.comparable,ex.comparable);
 for(const code of ex.requiredSections??[])assert.ok(o.sections.some(s=>s.sectionCode===code));for(const [code,state]of Object.entries(ex.sectionStatus??{}))assert.equal(o.sections.find(s=>s.sectionCode===code)?.status,state);
 for(const fragment of ex.forbiddenText??[])assert.ok(!o.claims.some(c=>c.textRu.includes(fragment)));
 for(const spec of ex.claims??[]){const cs=o.claims.filter(c=>c.claimCode===spec.code);assert.ok(cs.length,'Missing asserted claim');assert.ok(cs.some(c=>Object.entries(spec).every(([key,v])=>key==='code'||(Array.isArray(v)?v.every(value=>c[key].includes(value)):c[key]===v))),'Claim contract '+spec.code);}
 for(const code of ex.requiredLimitations??[])assert.ok(o.claims.some(c=>c.claimCode==='LIMITATION:'+code));for(const kind of ex.requiredSourceKinds??[])assert.ok(o.sourceReferences.some(s=>s.sourceKind===kind));
 for(const [key,limit]of Object.entries(ex.executiveLimits??{}))assert.ok(o.executiveSummary[key].length<=limit);
 if(ex.completeCoverage)assert.deepEqual(o.coverageReport.unmappedCodes,[]);
}
